package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.io.File;import java.util.concurrent.*;

public class DocumentActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private VaultRepository repo;private JSONObject doc;private LinearLayout page;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);if(!Session.valid()){finish();return;}repo=new VaultRepository(this);shell();load();}
 private void shell(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=Ui.column(this);page.setPadding(Ui.dp(this,18),Ui.dp(this,14),Ui.dp(this,18),Ui.dp(this,28));page.setBackgroundColor(Ui.BG);scroll.addView(page);setContentView(scroll);}
 private void load(){String id=getIntent().getStringExtra("id");io.execute(()->{try{doc=repo.get(id);if(doc==null)throw new IllegalStateException();runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->{Ui.toast(this,"Document not found");finish();});}});}
 private void render(){page.removeAllViews();LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=Ui.text(this,"‹",38,Ui.INK);back.setGravity(Gravity.CENTER);back.setContentDescription("Back");back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));LinearLayout titles=Ui.column(this);titles.addView(Ui.title(this,doc.optString("title"),23));titles.addView(Ui.text(this,doc.optString("category","Other")+" · Encrypted",13,Ui.TEAL));bar.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView menu=Ui.text(this,"⋮",30,Ui.INK);menu.setGravity(Gravity.CENTER);menu.setContentDescription("Document Options");menu.setOnClickListener(v->options(menu));bar.addView(menu,new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,46)));page.addView(bar);LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER);TextView pdf=Ui.pill(this,"PDF",Ui.NAVY),word=Ui.pill(this,"WORD",Ui.TEAL),print=Ui.pill(this,"PRINT",0xff6b7f79);pdf.setOnClickListener(v->layoutChoice("pdf",false));word.setOnClickListener(v->layoutChoice("docx",false));print.setOnClickListener(v->layoutChoice("pdf",true));for(TextView action:new TextView[]{pdf,word,print}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,45),1);p.setMargins(Ui.dp(this,4),Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,16));actions.addView(action,p);}page.addView(actions);TextView privacy=Ui.text(this,"Decrypted only for this private preview. Exports are created only when you choose an action above.",12,Ui.MUTED);privacy.setGravity(Gravity.CENTER);privacy.setPadding(Ui.dp(this,12),0,Ui.dp(this,12),Ui.dp(this,14));page.addView(privacy);JSONArray pages=doc.optJSONArray("pages");for(int i=0;pages!=null&&i<pages.length();i++){int index=i;FrameLayout frame=new FrameLayout(this);frame.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8));frame.setBackground(Ui.stroke(Color.WHITE,Ui.dp(this,1),0xffd2dcda,Ui.dp(this,16)));frame.setElevation(Ui.dp(this,3));ProgressBar loading=new ProgressBar(this);frame.addView(loading,new FrameLayout.LayoutParams(Ui.dp(this,38),Ui.dp(this,38),Gravity.CENTER));TextView number=Ui.text(this,(i==0&&pages.length()==2?"FRONT":i==1&&pages.length()==2?"BACK":"PAGE "+(i+1)),11,Color.WHITE);number.setGravity(Gravity.CENTER);number.setTypeface(null,android.graphics.Typeface.BOLD);number.setBackground(Ui.bg(Ui.NAVY,Ui.dp(this,12)));FrameLayout.LayoutParams np=new FrameLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,25),Gravity.TOP|Gravity.START);np.setMargins(Ui.dp(this,13),Ui.dp(this,13),0,0);frame.addView(number,np);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,Ui.dp(this,430));fp.bottomMargin=Ui.dp(this,14);page.addView(frame,fp);io.execute(()->loadPage(frame,loading,index));}}
 private void loadPage(FrameLayout frame,View loading,int index){try{byte[] data=repo.page(doc,index);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(data,0,data.length,bounds);int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>1800)sample*=2;BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeByteArray(data,0,data.length,o);runOnUiThread(()->{if(isFinishing()){bitmap.recycle();return;}ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);frame.addView(image,0,new FrameLayout.LayoutParams(-1,-1));frame.removeView(loading);});}catch(Exception e){runOnUiThread(()->{frame.removeView(loading);TextView error=Ui.text(this,"Could Not Decrypt This Page",14,0xffb33a3a);error.setGravity(Gravity.CENTER);frame.addView(error,new FrameLayout.LayoutParams(-1,-1));});}}
 private void layoutChoice(String format,boolean print){boolean multiple=doc.optJSONArray("pages").length()>1;if(!multiple){export(format,false,print);return;}String[] items={"Front And Back Centered On One Page","Place Each Side On Its Own Page"};new AlertDialog.Builder(this).setTitle(print?"Print Layout":"Export Layout").setSingleChoiceItems(items,0,null).setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,w)->export(format,((AlertDialog)d).getListView().getCheckedItemPosition()==0,print)).show();}
 private void export(String format,boolean together,boolean print){ProgressDialog wait=new ProgressDialog(this);wait.setMessage(print?"Preparing print copy…":"Creating secure export…");wait.setCancelable(false);wait.show();io.execute(()->{try{DocumentExporter ex=new DocumentExporter(this);File f=format.equals("docx")?ex.docx(doc,together):ex.pdf(doc,together);runOnUiThread(()->{wait.dismiss();if(print)ex.print(this,f,doc.optString("title","Document"));else ex.share(f,format.equals("docx")?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"application/pdf");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could not create the export");});}});}
 private void options(View anchor){PopupWindow pop=new PopupWindow(this);LinearLayout list=Ui.column(this);String[] names={"Rename Document","Change Category","Delete From Wallet"};for(String name:names){TextView item=Ui.text(this,name,15,name.startsWith("Delete")?0xffb3261e:Ui.INK);item.setPadding(Ui.dp(this,18),0,Ui.dp(this,18),0);item.setOnClickListener(v->{pop.dismiss();if(name.startsWith("Rename"))edit(false);else if(name.startsWith("Change"))edit(true);else confirmDelete();});list.addView(item,new LinearLayout.LayoutParams(Ui.dp(this,210),Ui.dp(this,50)));}list.setBackground(Ui.bg(Color.WHITE,Ui.dp(this,12)));pop.setContentView(list);pop.setWidth(Ui.dp(this,210));pop.setHeight(-2);pop.setBackgroundDrawable(Ui.bg(Color.WHITE,Ui.dp(this,12)));pop.setElevation(Ui.dp(this,10));pop.setOutsideTouchable(true);pop.setFocusable(true);pop.showAsDropDown(anchor,-Ui.dp(this,170),0);}
 private void edit(boolean categoryOnly){if(categoryOnly){String[] values={"Identity","Driver Permit / Licence","Certificate","Medical","Financial","Other"};new AlertDialog.Builder(this).setTitle("Change Category").setItems(values,(d,i)->saveEdit(doc.optString("title"),values[i])).show();return;}EditText name=Ui.field(this,"Document name",false);name.setText(doc.optString("title"));FrameLayout wrap=new FrameLayout(this);wrap.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),0);wrap.addView(name,new FrameLayout.LayoutParams(-1,Ui.dp(this,56)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Rename Document").setView(wrap).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim();if(n.isEmpty()){name.setError("Enter a name");return;}dialog.dismiss();saveEdit(n,doc.optString("category","Other"));}));dialog.show();}
 private void saveEdit(String title,String category){io.execute(()->{try{repo.rename(doc.getString("id"),title,category);doc.put("title",title).put("category",category);runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could not update the document"));}});}
 private void confirmDelete(){new AlertDialog.Builder(this).setTitle("Delete Document?").setMessage("This permanently removes every encrypted page from this phone. This cannot be undone.").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->io.execute(()->{try{repo.delete(doc.getString("id"));runOnUiThread(()->{Ui.toast(this,"Document deleted");finish();});}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could not delete the document"));}})).show();}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onResume(){super.onResume();if(!Session.valid())finish();}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
